<?php
$pageTitle='Notificacoes | CEPIN-CIS';$bodyClass='app-page notifications-page';require_once 'controllers/AuthController.php';require_once 'models/ProjectWorkspace.php';$auth=new AuthController();$auth->requireAuth();$u=$auth->getCurrentUser();$wm=new ProjectWorkspaceManager();if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['notification_id']))$wm->markNotificationRead((string)$_POST['notification_id'],(int)$u['id']);$items=$wm->listNotifications((int)$u['id']);include 'includes/header.php';?><main class="page-shell"><section class="panel-card"><p class="eyebrow">Central</p><h1>Notificacoes</h1><?php if(!$items):?><p>Nenhuma notificacao.</p><?php endif;?><?php foreach($items as $n):?><article class="panel-card"><small><?php echo htmlspecialchars($n['created_at']);?></small><h2><?php echo htmlspecialchars($n['title']);?></h2><p><?php echo htmlspecialchars((string)$n['body']);?></p><?php if(!empty($n['target_url'])):?><a href="<?php echo htmlspecialchars($n['target_url']);?>">Abrir</a><?php endif;?><?php if($n['read_at']===null):?><form method="post"><input type="hidden" name="notification_id" value="<?php echo htmlspecialchars($n['id']);?>"><button type="submit">Marcar como lida</button></form><?php endif;?></article><?php endforeach;?></section></main><?php include 'includes/footer.php';?>
